# Headless run of the four analyses (the .b.R classes). Run from the module root. Best run in jamovi's own R with the jamovi libraries.
suppressMessages({library(jmvcore); library(R6); library(ggplot2); library(Matrix)})
for (f in c("R/00jmv.R", list.files("R", "^(common|guide|engine_.*)[.]R$", full.names = TRUE),
            list.files("R", "[.]h[.]R$", full.names = TRUE), list.files("R", "[.]b[.]R$", full.names = TRUE))) source(f)
col <- read.csv("data/columbus.csv"); nc <- read.csv("data/nc_sids.csv")
bad <- 0
run <- function(label, fn, data, ...) {
    a <- list(...)
    fm <- formals(fn)
    for (n in setdiff(names(fm)[vapply(fm, function(z) identical(z, quote(expr = )), logical(1))], c("data", names(a)))) a[n] <- list(NULL)
    r <- tryCatch({ res <- do.call(fn, c(list(data = data), a)); invisible(capture.output(print(res))); "ok" }, error = function(e) paste("ERROR:", conditionMessage(e)))
    cat(sprintf("%-52s %s\n", label, substr(r, 1, 110))); r
}
ok <- function(label, fn, data, ...) { r <- run(label, fn, data, ...); if (r != "ok") bad <<- bad + 1 }
err <- function(label, fn, data, ...) { r <- run(label, fn, data, ...); if (!grepl("^ERROR", r)) { cat("  expected an error\n"); bad <<- bad + 1 } }
geo <- file.path(getwd(), "data/columbus.geojson"); edges <- file.path(getwd(), "data/columbus_edges.csv"); ncshp <- file.path(getwd(), "data/nc.shp")
cw <- list(idVar = "id", wSource = "boundary", wFile = geo, wIdField = "id", wMethod = "queen")
# --- swm
ok("swm coordinates", swm, col, xVar = "X", yVar = "Y", wMethod = "knn", wK = 4, histPlot = TRUE, showGuide = TRUE, showHelp = TRUE)
