# --- spdid
sdd <- read.csv("data/spillover_did.csv")
bs <- list(dep = "outcome", treat = "treat", timeVar = "year", idVar = "unit", xVar = "cx", yVar = "cy")
okS <- function(label, ...) do.call(ok, c(list(label, spdid, sdd), bs, list(...)))
errS <- function(label, ...) do.call(err, c(list(label, spdid, sdd), bs, list(...)))
okS("spdid rings, clustered", covs = "x1", rings = "10, 20", showGuide = TRUE, showHelp = TRUE)
okS("spdid rings, robust, unit effects", rings = "15", se = "robust", effects = "unit")
okS("spdid Conley", rings = "10, 20", se = "conley", conleyBw = 25, conleyLag = 2)
okS("spdid lagged treatment", lagTreat = TRUE, wMethod = "knn", wK = 4)
okS("spdid rings and lag", rings = "10", lagTreat = TRUE)
errS("spdid no spillover term")
errS("spdid bad rings", rings = "20, 10")
errS("spdid ring without units", rings = "0.001, 0.002")
errS("spdid Conley without bandwidth", rings = "10", se = "conley")
